```python
"""A background worker that drains a queue.Queue, handing each item to a callback."""

import logging
import queue
import threading

log = logging.getLogger(__name__)


class _Shutdown:
    """Sentinel: put it on the queue to end the worker after the backlog drains."""

    __slots__ = ()

    def __repr__(self):
        return "SHUTDOWN"


SHUTDOWN = _Shutdown()


class QueueWorker:
    """Runs `callback(item)` on a daemon thread for every item put on the queue."""

    SHUTDOWN = SHUTDOWN

    def __init__(self, callback, q=None, name="queue-worker"):
        self.callback = callback
        self.queue = q if q is not None else queue.Queue()
        self.stopped = threading.Event()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def submit(self, item):
        if self.stopped.is_set():
            raise RuntimeError("worker is shutting down")
        self.queue.put(item)

    def _run(self):
        try:
            while True:
                item = self.queue.get()
                try:
                    if item is SHUTDOWN:
                        log.debug("worker received sentinel; shutting down")
                        return
                    self.callback(item)
                except Exception:
                    # One bad item shouldn't take the worker down.
                    log.exception("worker callback failed on %r", item)
                finally:
                    self.queue.task_done()
        finally:
            self.stopped.set()

    def join_queue(self):
        """Block until everything submitted so far has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Ask the worker to finish the backlog, then exit. Idempotent."""
        if not self._started:
            self.stopped.set()
            return True
        if not self.stopped.is_set():
            self.queue.put(SHUTDOWN)
        self._thread.join(timeout)
        return not self._thread.is_alive()

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False
```

The sentinel is now a public value (`SHUTDOWN`, also reachable as `QueueWorker.SHUTDOWN`), so any producer can end the worker by putting it on the queue — useful when the producer is the one that knows the stream is finished, or when several producers share a queue you didn't create. It's a class instance rather than `object()` purely so log lines and tracebacks read `SHUTDOWN` instead of `<object at 0x…>`.

Shutdown ordering: the sentinel travels through the queue, so items submitted before it are all processed first; anything put after it is left in the queue untouched. `stop()` is idempotent, returns `True` if the thread actually exited within `timeout` (`False` means it's still inside a slow callback), and `stopped` is a public `Event` you can wait on from elsewhere. `submit()` raises once shutdown has happened, so a late producer fails loudly instead of silently dropping work into a dead queue.

One caveat worth knowing: if a producer puts `SHUTDOWN` directly, `stop()` afterwards won't add a second one only if `stopped` is already set — during the brief window before the worker processes the sentinel, `stop()` may enqueue a redundant one that is simply never consumed. Harmless, but it means `join_queue()` after that race can block; call `stop()` rather than `join_queue()` when you're winding down.
